CREATE TABLE users (id UUID PRIMARY KEY, created_at TIMESTAMPTZ NOT NULL, updated_at TIMESTAMPTZ NOT NULL, created_by UUID, updated_by UUID, version BIGINT NOT NULL, normalized_email VARCHAR(320) NOT NULL UNIQUE, password_hash VARCHAR(100) NOT NULL, display_name VARCHAR(120) NOT NULL, status VARCHAR(32) NOT NULL CHECK (status IN ('ACTIVE','LOCKED','DISABLED','PENDING_VERIFICATION')), email_verified BOOLEAN NOT NULL DEFAULT FALSE, failed_login_count INTEGER NOT NULL DEFAULT 0 CHECK (failed_login_count >= 0), locked_until TIMESTAMPTZ, last_login_at TIMESTAMPTZ);
CREATE INDEX idx_users_normalized_email ON users(normalized_email);
CREATE TABLE refresh_tokens (id UUID PRIMARY KEY, created_at TIMESTAMPTZ NOT NULL, updated_at TIMESTAMPTZ NOT NULL, created_by UUID, updated_by UUID, version BIGINT NOT NULL, user_id UUID NOT NULL, token_hash VARCHAR(64) NOT NULL UNIQUE, issued_at TIMESTAMPTZ NOT NULL, expires_at TIMESTAMPTZ NOT NULL, revoked_at TIMESTAMPTZ, replaced_by_token_id UUID, client_metadata VARCHAR(256));
CREATE INDEX idx_refresh_tokens_user_expiry ON refresh_tokens(user_id, expires_at); CREATE INDEX idx_refresh_tokens_hash ON refresh_tokens(token_hash);
CREATE TABLE workspaces (id UUID PRIMARY KEY, created_at TIMESTAMPTZ NOT NULL, updated_at TIMESTAMPTZ NOT NULL, created_by UUID, updated_by UUID, version BIGINT NOT NULL, name VARCHAR(160) NOT NULL, slug VARCHAR(160) NOT NULL UNIQUE, description VARCHAR(2000), status VARCHAR(32) NOT NULL CHECK (status IN ('ACTIVE','SUSPENDED','ARCHIVED')), creator_user_id UUID NOT NULL);
CREATE INDEX idx_workspaces_slug ON workspaces(slug);
CREATE TABLE workspace_members (id UUID PRIMARY KEY, created_at TIMESTAMPTZ NOT NULL, updated_at TIMESTAMPTZ NOT NULL, created_by UUID, updated_by UUID, version BIGINT NOT NULL, workspace_id UUID NOT NULL REFERENCES workspaces(id), user_id UUID NOT NULL, role VARCHAR(32) NOT NULL CHECK (role IN ('OWNER','ADMIN','MEMBER','VIEWER','AUDITOR')), status VARCHAR(32) NOT NULL CHECK (status IN ('ACTIVE','INVITED','SUSPENDED','REMOVED')), joined_at TIMESTAMPTZ NOT NULL, invited_by_user_id UUID, CONSTRAINT uk_workspace_member_user UNIQUE(workspace_id,user_id));
CREATE INDEX idx_workspace_members_workspace_status ON workspace_members(workspace_id,status); CREATE INDEX idx_workspace_members_user_status ON workspace_members(user_id,status);
CREATE TABLE workspace_invitations (id UUID PRIMARY KEY, created_at TIMESTAMPTZ NOT NULL, updated_at TIMESTAMPTZ NOT NULL, created_by UUID, updated_by UUID, version BIGINT NOT NULL, workspace_id UUID NOT NULL REFERENCES workspaces(id), invitee_email VARCHAR(320) NOT NULL, role VARCHAR(32) NOT NULL CHECK (role IN ('OWNER','ADMIN','MEMBER','VIEWER','AUDITOR')), token_hash VARCHAR(64) NOT NULL UNIQUE, invited_by_user_id UUID NOT NULL, expires_at TIMESTAMPTZ NOT NULL, accepted_at TIMESTAMPTZ, revoked_at TIMESTAMPTZ, status VARCHAR(32) NOT NULL CHECK (status IN ('PENDING','ACCEPTED','EXPIRED','REVOKED')));
CREATE UNIQUE INDEX uk_workspace_pending_invitation ON workspace_invitations(workspace_id,invitee_email) WHERE status='PENDING'; CREATE INDEX idx_workspace_invitations_token_hash ON workspace_invitations(token_hash); CREATE INDEX idx_workspace_invitations_email_status ON workspace_invitations(invitee_email,workspace_id,status);
CREATE TABLE audit_records (id UUID PRIMARY KEY, created_at TIMESTAMPTZ NOT NULL, updated_at TIMESTAMPTZ NOT NULL, created_by UUID, updated_by UUID, version BIGINT NOT NULL, actor_user_id UUID, action VARCHAR(80) NOT NULL, workspace_id UUID, resource_type VARCHAR(80) NOT NULL, resource_id UUID, correlation_id VARCHAR(128), metadata JSONB);
CREATE INDEX idx_audit_workspace_timestamp ON audit_records(workspace_id,created_at DESC); CREATE INDEX idx_audit_actor_timestamp ON audit_records(actor_user_id,created_at DESC); CREATE INDEX idx_audit_action_timestamp ON audit_records(action,created_at DESC);
